python3 -c "
import pandas as pd

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')

def parse_val(v):
    v = str(v).strip().replace(',', '.')
    try:
        return float(v)
    except:
        return None

# Check all columns for range patterns
cols_to_check = df.columns[1:]  # skip patient_id
for col in cols_to_check:
    parsed = df[col].dropna().apply(parse_val).dropna()
    if len(parsed) == 0:
        continue
    print(f'{col}: min={parsed.min():.4f}, max={parsed.max():.4f}, mean={parsed.mean():.4f}, median={parsed.median():.4f}, count={len(parsed)}')
